var n=`0505-knafeh-nabulsi`;var i=`world-0505`;var t=`PS`;var r=`western-asia`;var s=8;var o=57;var l={en:`Knafeh Nabulsi`,ua:`Кнафе по-наблуськи`};var d={en:`A traditional dish from Palestine, centered on phyllo pastry, mozzarella, pistachio. A measured home-kitchen version organized by cooking step. Knafeh Nabulsi-inspired dessert with phyllo and mozzarella instead of traditional kataifi and Nabulsi cheese, both absent from the catalog.`,ua:`Традиційна страва кухні країни Палестина. Основні складники: тісто філо, моцарела, фісташка. Домашній варіант із кількостями продуктів за етапами приготування. Десерт у стилі наблуського кнафе із філо та моцарелою замість традиційного катаїфі й сиру набулсі, відсутніх у каталозі.`};var u=[{en:`Shred phyllo and arrange it over the buttered pan around a layer of cheese; this replaces unavailable kataifi pastry.`,ua:`Наріжте філо тонко й викладіть у змащену форму навколо шару сиру; це заміна відсутнього катаїфі.`,t:[`layered-assembly`],m:14,i:[[`phyllo-pastry`,420,`g`],[`unsalted-butter`,190,`g`],[`mozzarella`,420,`g`]]},{en:`Roast in a preheated 190°C oven for about 28 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 28 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:28,i:[]},{en:`Simmer the liquid and flavorings uncovered for about 12 minutes until reduced and concentrated.`,ua:`Уварюйте рідину з приправами без кришки приблизно 12 хвилин до насичення та загустіння.`,t:[`reducing-sauce`],m:12,i:[[`white-granulated-sugar`,300,`g`],[`water`,270,`ml`],[`rose-water`,17,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`pistachio`,60,`g`]]}];var h={slug:n,id:i,country:`PS`,region:r,servings:8,minutes:57,title:l,text:d,steps:u};export{t as country,h as default,i as id,o as minutes,r as region,s as servings,n as slug,u as steps,d as text,l as title};